def solve(params, ctx):
    events = params["events"]

    is_running = False
    start_time = None
    total_seconds = 0

    for event in events:
        ts = event["ts"]
        event_type = event["event"]

        if event_type == "start":
            if not is_running:
                is_running = True
                start_time = ts
        elif event_type == "stop":
            if is_running:
                total_seconds += ts - start_time
                is_running = False

    return {"seconds": total_seconds}
